from dataclasses import dataclass

TTL_SECONDS = 1800          # todo bloqueo expira
APPROVAL_ABOVE = 50         # un alcance grande exige a un humano

@dataclass
class Alert:
    id: str
    source_ips: list[str]
    confidence: float

def run(alert: Alert, *, dry_run: bool = True) -> str:
    if audit.already_handled(alert.id):          # idempotencia
        return "skip: ya tratado"
    if alert.confidence < 0.9:
        return "skip: confianza baja, va a triaje humano"

    if len(alert.source_ips) > APPROVAL_ABOVE and not approvals.granted(alert.id):
        approvals.request(alert.id, reason="bloqueo amplio")
        return "pendiente: esperando aprobación"

    for ip in alert.source_ips:
        blocker.block(ip, ttl=TTL_SECONDS, dry_run=dry_run)
    audit.record(alert.id, action="block", ips=alert.source_ips, dry_run=dry_run)
    return "ok"
